import gzip,glob,re
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if l.startswith('!'):
    vals=l.rstrip().split('\t'); uniq=list(dict.fromkeys(vals[1:]))
    for v in uniq:
     if re.search(r'\d\s*(?:[nuμµmM]M|mol|M\b)',v): print(vals[0],v)

